async () => {
  const start = Date.now();
  while (Date.now() - start < 60000) {
    const cards = document.querySelectorAll('[data-testid="query-result-card"], [aria-label="query-result-card"]');
    const loadingText = document.body.innerText.includes('AI 正在解析');
    const allText = document.body.innerText;
    const count = (allText.match(/演示数据：当前数据源不支持真实查询/g) || []).length;
    if (count >= 2 && !loadingText) {
      return { done: true, cards: cards.length, demoNotices: count, waitedMs: Date.now() - start };
