() => {
  const rgbToHex = (rgb) => {
    const m = rgb.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)(?:,\s*([\d.]+))?\)/);
    if (!m) return rgb;
    const a = m[4] !== undefined ? parseFloat(m[4]) : 1;
    const hex = [m[1], m[2], m[3]].map(x => (+x).toString(16).padStart(2, '0')).join('');
    return `#${hex}${a < 1 ? ' a=' + a : ''}`;
  };
  const luminance = (rgb) => {
    const m = rgb.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
    if (!m) return null;
    const f = c => { c /= 255; return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4); };
    return 0.2126 * f(+m[1]) + 0.7152 * f(+m[2]) + 0.0722 * f(+m[3]);
  };
  const contrast = (fg, bg) => {
    const l1 = luminance(fg), l2 = luminance(bg);
    if (l1 === null || l2 === null) return null;
    const [hi, lo] = l1 > l2 ? [l1, l2] : [l2, l1];
    return Math.round(((hi + 0.05) / (lo + 0.05)) * 100) / 100;
  };
  // effective background: walk up until non-transparent
  const effectiveBg = (el) => {
    let node = el;
    while (node && node !== document.documentElement) {
      const bg = getComputedStyle(node).backgroundColor;
      const m = bg.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)(?:,\s*([\d.]+))?\)/);
      if (m && (m[4] === undefined || parseFloat(m[4]) > 0.9)) return bg;
      if (m && m[4] !== undefined && parseFloat(m[4]) > 0) return bg + ' (semi)';
      node = node.parentElement;
    }
    return getComputedStyle(document.body).backgroundColor;
  };

  const findAll = (needle) => {
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    const out = [];
    while (walker.nextNode()) {
      if (walker.currentNode.textContent.includes(needle)) out.push(walker.currentNode.parentElement);
    }
    return out;
  };

  const report = (label, el) => {
    if (!el) return { label, found: false };
    const cs = getComputedStyle(el);
    const bg = effectiveBg(el);
    return {
      label, found: true,
      color: rgbToHex(cs.color),
      bg: rgbToHex(bg),
      contrast: contrast(cs.color, bg)
    };
  };

  const demo = findAll('演示数据：当前数据源不支持真实查询');
  const attr = findAll('AI 归因分析与决策提示');
  const kpi = findAll('较上半年效能显著提升');
  const insight = findAll('效能拐点明确');
  const body2 = findAll('由于当前数据源');

  return {
    demoNotice: demo.map((el, i) => report('演示提示#' + i, el)),
    attribution: attr.map((el, i) => report('归因标题#' + i, el)),
    attributionBody: insight.map((el, i) => report('归因正文#' + i, el)),
    kpiSub: kpi.map((el, i) => report('KPI副文#' + i, el)),
    analysisBody: body2.map((el, i) => report('分析正文#' + i, el))
  };
}

() => {
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  const els = [];
  while (walker.nextNode()) {
    if (walker.currentNode.textContent.includes('演示数据：当前数据源不支持真实查询')) els.push(walker.currentNode.parentElement);
  }
  const chainInfo = (el) => {
    const chain = [];
    let node = el;
    for (let i = 0; i < 6 && node && node !== document.body; i++) {
      const cs = getComputedStyle(node);
      chain.push({
        tag: node.tagName,
        cls: (node.className || '').toString().slice(0, 80),
        bg: cs.backgroundColor,
        bgImage: cs.backgroundImage !== 'none' ? cs.backgroundImage.slice(0, 60) : 'none',
        color: cs.color,
        border: cs.border
      });
      node = node.parentElement;
    }
    return chain;
  };
  return els.map((el, i) => ({ idx: i, chain: chainInfo(el) }));
}

