    if (walker2.currentNode.textContent.includes('演示数据：当前数据源不支持真实查询')) { demoEl = walker2.currentNode.parentElement; break; }
  }
  const demoInfo = demoEl ? { fontSize: getComputedStyle(demoEl.closest('div')).fontSize, fontWeight: getComputedStyle(demoEl).fontWeight, cls: demoEl.closest('div').className } : null;
  return { attribution: els.map((el, i) => ({ idx: i, chain: info(el) })), demoCard: demoInfo };
}

() => {
  const lum = (rgb) => {
    const m = rgb.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
    if (!m) return null;
    const f = c => { c /= 255; return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4); };
    return 0.2126 * f(+m[1]) + 0.7152 * f(+m[2]) + 0.0722 * f(+m[3]);
  };
  const effectiveBg = (el) => {
    let node = el;
    const layers = [];
    while (node && node !== document.documentElement) {
      const bg = getComputedStyle(node).backgroundColor;
      const m = bg.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)(?:,\s*([\d.]+))?\)/);
      if (m) {
        const a = m[4] === undefined ? 1 : parseFloat(m[4]);
        if (a > 0) layers.push({ r: +m[1], g: +m[2], b: +m[3], a });
      }
      node = node.parentElement;
    }
    let r = 255, g = 255, b = 255;
    for (let i = layers.length - 1; i >= 0; i--) {
      const L = layers[i];
      r = L.r * L.a + r * (1 - L.a);
      g = L.g * L.a + g * (1 - L.a);
      b = L.b * L.a + b * (1 - L.a);
    }
    return `rgb(${Math.round(r)}, ${Math.round(g)}, ${Math.round(b)})`;
  };
  const main = document.querySelector('main') || document.body;
  const bad = [];
  const els = main.querySelectorAll('*');
  for (const el of els) {
    if (!el.textContent || el.children.length > 0) continue;
    const txt = el.textContent.trim();
    if (!txt || txt.length > 60) continue;
    const rect = el.getBoundingClientRect();
    if (rect.width === 0 || rect.height === 0) continue;
    const cs = getComputedStyle(el);
    if (cs.visibility === 'hidden' || cs.display === 'none' || parseFloat(cs.opacity) < 0.1) continue;
    const fg = cs.color;
    const bg = effectiveBg(el);
    const l1 = lum(fg), l2 = lum(bg);
    if (l1 === null || l2 === null) continue;
    const c = (Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05);
    if (c < 3) bad.push({ text: txt.slice(0, 30), fg, bg, contrast: c.toFixed(2) });
  }
  return { lowContrastCount: bad.length, samples: bad.slice(0, 15) };
}

() => {
  const findByText = (needle) => {
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    while (walker.nextNode()) {
      if (walker.currentNode.textContent.trim() === needle) return walker.currentNode.parentElement;
    }
    return null;
  };
  const inspect = (txt) => {
    let el = findByText(txt);
    const trail = [];
    let guard = 0;
    while (el && guard < 4) {
      const cs = getComputedStyle(el);
      trail.push({ tag: el.tagName, bg: cs.backgroundColor, bgImage: cs.backgroundImage !== 'none' ? cs.backgroundImage.slice(0, 90) : 'none', color: cs.color, disabled: el.disabled });
      if (cs.backgroundColor !== 'rgba(0, 0, 0, 0)' || cs.backgroundImage !== 'none') break;
      el = el.parentElement; guard++;
    }
    return trail;
  };
  return {
    折线图: inspect('折线图'),
    固定至看板: inspect('固定至看板'),
    用户气泡: inspect('请按月份统计营收变化趋势'),
    智能查询: inspect('智能查询')
  };
}

