() => {
  const cards = document.querySelectorAll('[aria-label="query-result-card"], [data-res-card], .query-result-card');
  if (cards.length === 0) {
    // fallback: find element containing latest demo notice
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    const notices = [];
    while (walker.nextNode()) {
      if (walker.currentNode.textContent.includes('演示数据：当前数据源不支持真实查询')) notices.push(walker.currentNode.parentElement);
    }
    const last = notices[notices.length - 1];
    if (last) { last.scrollIntoView({ block: 'center' }); return { method: 'notice', count: notices.length }; }
    return { method: 'none', count: 0 };
  }
  cards[cards.length - 1].scrollIntoView({ block: 'start' });
  return { method: 'card', count: cards.length };
}

